sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = unpremul(image.eval(coord));
    half3 brown = luma(c.rgb) * half3(1.12, 0.92, 0.68) + half3(0.04, 0.02, 0);
    return half4(mix(c.rgb, saturate(brown), half(amount)) * c.a, c.a);
}
